
/* Approved MASTER DESIGN, presented as visual landing; GIS is separately selectable. */
#wowMaster{position:fixed;inset:0;z-index:850;background:#103a32 url('data:image/webp;base64,') center center/100% 100% no-repeat;color:white;font-family:Segoe UI,Arial,sans-serif;overflow:hidden}
#wowMaster[hidden],#wowZonePicker[hidden]{display:none!important}
#wowMaster .hot{position:absolute;border:0;background:transparent;cursor:pointer;border-radius:16px;color:transparent;font-size:1px;transition:background .2s,box-shadow .2s}
#wowMaster .hot:hover,#wowMaster .hot:focus-visible{background:#ffffff2b;box-shadow:inset 0 0 0 3px #fff8ad;outline:0}
#wowMaster .master-note{position:absolute;bottom:1.5%;left:1.5%;background:#07382bdc;border:1px solid #ffffff55;border-radius:12px;padding:7px 11px;font-size:clamp(9px,.78vw,12px);max-width:70%;line-height:1.3}
#wowMaster .master-actions{position:absolute;top:10%;right:1%;display:flex;gap:8px;z-index:2}
#wowMaster .master-actions button{font-size:clamp(11px,.92vw,15px);border:1px solid #ffffffad;background:#073a2be8;color:#fff;padding:9px 13px;border-radius:11px;font-weight:750;cursor:pointer;box-shadow:0 4px 16px #0005}
#wowMaster .master-actions button:hover{background:#17664a}
#wowZonePicker{position:fixed;inset:0;z-index:950;background:#061a15ba;display:flex;align-items:center;justify-content:center;padding:16px;font-family:Segoe UI,Arial}
#wowZonePicker .picker-card{width:min(780px,100%);max-height:88vh;overflow:auto;background:#f7fbf5;color:#10382c;border-radius:23px;padding:24px;box-shadow:0 22px 70px #0009}
#wowZonePicker h2{margin:0 0 8px;font-size:23px}
#wowZonePicker .picker-top{display:flex;justify-content:space-between;gap:15px;align-items:center}
#wowZonePicker button{cursor:pointer}
#wowZonePicker #wowZoneSearch{width:100%;padding:13px;border:1px solid #b6cfc1;border-radius:12px;font-size:16px;box-sizing:border-box;margin:14px 0}
#wowZoneGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:9px}
#wowZoneGrid button{padding:13px;border:1px solid #c6ddd1;background:white;border-radius:12px;text-align:left;color:#1b4d3c;font-weight:700}
#wowZoneGrid button:hover,#wowZoneGrid button:focus-visible{background:#e4f5e7;border-color:#65b279}
#wowZonePicker .close{background:#e8eee9;border:0;border-radius:50%;width:37px;height:37px;font-size:22px}
#wowBackToMaster{position:fixed;top:84px;left:18px;z-index:750;display:none;background:#104b36;color:#fff;border:1px solid #b6dfbf;border-radius:12px;padding:10px 13px;cursor:pointer;font-weight:750;box-shadow:0 3px 15px #0003}
body.wow-engine #wowBackToMaster{display:block}
/* One canonical pair: no old avatar docks or simplified V13 vectors. */
body.wow-live #teraAvatarDock,body.wow-live #tpuTeraFigure,body.wow-live #natuDock,
body.wow-live #tpuGuidePanel #tpuTeraFigure{display:none!important}
body.wow-live #v13Tera>svg,body.wow-live #v13Natu>svg{display:none!important}
body.wow-live #v13Tera,body.wow-live #v13Natu{background-position:center;background-repeat:no-repeat;background-size:contain;filter:drop-shadow(0 7px 9px #0006)!important;animation:masterHover 3.5s ease-in-out infinite alternate!important}
body.wow-live #v13Tera{background-image:url('tera_master.png');width:110px!important;height:125px!important}
body.wow-live #v13Natu{background-image:url('natu_master.png');width:105px!important;height:138px!important;animation-delay:-1.5s!important}
@keyframes masterHover{from{translate:0 -5px;rotate:-3deg}to{translate:0 8px;rotate:4deg}}
/* Engine background visually coordinated with the master; real zone geometries are kept separate. */
#gisViewport{background:#173b2d url('scenic_blurred.jpg') center/cover no-repeat!important}
#gisViewport::before,#gisViewport::after{display:none!important}
#gisShapes .gis-zone{fill-opacity:.85!important;stroke:#fff8c9!important;stroke-width:1.7!important}
#gisSvg{max-width:100%;max-height:100%}
/* Document mode: do not place characters over PDF pages or text panel. */
/* Actors remain present when document opens; placement is managed by the sync controller. */
body.wow-live:has(#tpuGuidePanel.open) #v13Tera{left:calc(100% - 125px)!important;top:18%!important}
body.wow-live:has(#tpuGuidePanel.open) #v13Natu{left:calc(100% - 125px)!important;top:68%!important}
@media(max-width:850px){#wowMaster{background-size:cover;background-position:center}#wowMaster .hot{display:none}#wowMaster .master-actions{top:auto;bottom:9%;right:4%;flex-direction:column}#wowMaster .master-note{bottom:1%;left:3%;max-width:75%}#wowZonePicker .picker-card{padding:15px}#wowBackToMaster{top:78px;left:7px;font-size:12px}}
@media(prefers-reduced-motion:reduce){body.wow-live #v13Tera,body.wow-live #v13Natu{animation:none!important}}
